import{M as e,_ as t,b as n,k as r,m as i,v as a}from"./app-Xgp6P-Ux.js";import{t as o}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var s=JSON.parse('{"path":"/Vpn-clash-win-mac/Clash-for-Android.html","title":"Clash for Android 教程","lang":"zh-CN","frontmatter":{"title":"Clash for Android 教程","date":"2023-06-11T14:49:10.000Z","author":"AI悦创","isOriginal":true,"category":["ChatGPT"],"tag":["ChatGPT"],"icon":"chat","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1686466968000,"updatedTime":1744328990000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":5,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"543d09dc896aa09b8fcad8d910662e397a86b448","time":1716982955000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"```card"},{"hash":"f42e6a26b484a1bc950104f2b034dfa2152ccb0a","time":1686482995000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"更新 vpn"},{"hash":"574e30b0a515323f9632474e76f09e2d608406cf","time":1686466968000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复主页链接"}]},"readingTime":{"minutes":2.14,"words":643},"filePathRelative":"Vpn-clash-win-mac/Clash-for-Android.md"}'),c={name:`Clash-for-Android.md`};function l(o,s,c,l,u,d){let f=e(`VPCard`);return r(),t(`div`,null,[s[0]||=i(`div`,{class:`hint-container info`},[i(`p`,{class:`hint-container-title`},`相关信息`),i(`p`,null,`仅供内部学习使用`)],-1),n(f,{title:`Clash for Android`,desc:`Android Clash 安装包`,logo:`/aiyc.svg`,link:`https://aiyc.lanzoum.com/iO1b50x3lesf`,background:`rgba(253, 230, 138, 0.15)`}),s[1]||=a(`<p>Clash For Android 是一款新推出的 V2ray 客户端。自带服务器测速，可用性测试等功能，用户不需要关心那个节点速度快慢，可用与否，十分适合新手用户。 <a href="https://github.com/Kr328/ClashForAndroid/releases/download/v2.5.11/cfa-2.5.11-foss-arm64-v8a-release.apk" target="_blank" rel="noopener noreferrer">点此直接下载Clash For Android</a> 如果在手机上无法下载 Clash，可以在电脑下载好，然后利用微信或者 QQ 传输到手机上，保存为手机上的文件，再利用手机的文件或者资源管理器。</p><h2 id="_1-复制你专属的订阅链接" tabindex="-1"><a class="header-anchor" href="#_1-复制你专属的订阅链接"><span>1. 复制你专属的订阅链接</span></a></h2><h3 id="_1-1-打开订阅网站" tabindex="-1"><a class="header-anchor" href="#_1-1-打开订阅网站"><span>1.1 打开订阅网站</span></a></h3><p><a href="https://mf.bornforthis.cn/content" target="_blank" rel="noopener noreferrer">https://mf.bornforthis.cn/content</a></p><p>需要密码，但凡购买的，都会给你开通专属有效期内的密码。</p><h3 id="_1-2-复制你的专属订阅链接" tabindex="-1"><a class="header-anchor" href="#_1-2-复制你的专属订阅链接"><span>1.2 复制你的专属订阅链接</span></a></h3><figure><img src="/assets/image-20230611150116625-CFR9olX5.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>进入之后。</p><h3 id="_1-3-选择复制安卓手机的订阅" tabindex="-1"><a class="header-anchor" href="#_1-3-选择复制安卓手机的订阅"><span>1.3 选择复制安卓手机的订阅</span></a></h3><figure><img src="/assets/image-20230611190811177-CI-OdDi2.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_2-手机配置" tabindex="-1"><a class="header-anchor" href="#_2-手机配置"><span>2. 手机配置</span></a></h2><h3 id="_2-1-手机上打开clash-选择配置" tabindex="-1"><a class="header-anchor" href="#_2-1-手机上打开clash-选择配置"><span>2.1 手机上打开clash, 选择配置</span></a></h3><figure><img src="/assets/s1-CWxsmZLx.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_2-2-选择-新配置" tabindex="-1"><a class="header-anchor" href="#_2-2-选择-新配置"><span>2.2 选择 +新配置</span></a></h3><figure><img src="/assets/s3-s520f-J4.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_2-3-选择从-url-导入" tabindex="-1"><a class="header-anchor" href="#_2-3-选择从-url-导入"><span>2.3 选择从 URL 导入</span></a></h3><figure><img src="/assets/s4-Dqw_xWcN.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_2-4-填写配置" tabindex="-1"><a class="header-anchor" href="#_2-4-填写配置"><span>2.4 填写配置</span></a></h3><p>按照下图备注填写， URL 就是之前从 <a href="https://mf.bornforthis.cn/content" target="_blank" rel="noopener noreferrer">https://mf.bornforthis.cn/content</a> 上复制的 Clash 订阅码链接地址。 此链接地址你也可以通过微信、QQ 等发送到手机上，然后复制。</p><figure><img src="/assets/s5_fix-BBF49wtj.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_2-5-选中-igg-然后返回" tabindex="-1"><a class="header-anchor" href="#_2-5-选中-igg-然后返回"><span>2.5 选中 IGG ， 然后返回</span></a></h3><figure><img src="/assets/s6-4kllyKsL.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_3-打开代理" tabindex="-1"><a class="header-anchor" href="#_3-打开代理"><span>3. 打开代理</span></a></h2><h3 id="_3-1-按下图点击-已停止-按钮开启-vpn-连接" tabindex="-1"><a class="header-anchor" href="#_3-1-按下图点击-已停止-按钮开启-vpn-连接"><span>3.1 按下图点击 已停止 按钮开启 VPN 连接</span></a></h3><figure><img src="/assets/s7-BK9CLb5C.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>按下图显示 运行中 ， 就代表连接成功。</p><figure><img src="/assets/s8-mPl4UnU2.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Linux、Web全栈」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,30)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};